"use client";

import { useState } from "react";
import Link from "next/link";
import styles from "./HotelOverview.module.css";
import type { HotelView, IconKey } from "@/lib/view-hotels";

const TABS = ["Overview", "Rooms", "Facilities", "Location", "Reviews"] as const;
type Tab = (typeof TABS)[number];

const ICONS: Record<IconKey, string> = {
  beach: "⛱",
  wifi: "📶",
  pool: "🏊",
  plane: "✈",
  spa: "💆",
  food: "🍽",
  bar: "🍸",
  gym: "🏋",
  car: "🅿",
  clock: "🕑",
};

const VISIBLE_ROOM_FACILITIES = 8;

export default function HotelOverview({ hotel }: { hotel: HotelView }) {
  const [activeTab, setActiveTab] = useState<Tab>("Overview");
  const [saved, setSaved] = useState(false);
  const [roomPhoto, setRoomPhoto] = useState<Record<string, number>>({});
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});

  const [hero, ...rest] = hotel.photos;
  const thumbs = rest.slice(0, 3);
  const moreImg = rest[3];
  const extraPhotos = hotel.photoCount - hotel.photos.length;

  return (
    <div className={styles.page}>
      {/* Gallery */}
      <section className={styles.gallery}>
        <div className={styles.mainPhoto}>
          {hero && <img src={hero.src} alt={hero.alt} />}
          <button
            type="button"
            className={styles.heart}
            aria-label={saved ? "Remove from saved" : "Save hotel"}
            aria-pressed={saved}
            onClick={() => setSaved((s) => !s)}
          >
            {saved ? "♥" : "♡"}
          </button>
        </div>

        <div className={styles.thumbs}>
          {thumbs.map((p) => (
            <img key={p.src} src={p.src} alt={p.alt} />
          ))}
          {moreImg && (
            <div className={styles.more}>
              <img src={moreImg.src} alt="" />
              {extraPhotos > 0 && <span>+{extraPhotos} photos</span>}
            </div>
          )}
        </div>
      </section>

      {/* Title row */}
      <section className={styles.titleRow}>
        <div>
          <div className={styles.titleLine}>
            <h1>{hotel.name}</h1>
            {hotel.stars > 0 && (
              <span className={styles.stars} aria-label={`${hotel.stars} star hotel`}>
                {"★".repeat(hotel.stars)}
              </span>
            )}
          </div>
          <div className={styles.location}>
            <svg viewBox="0 0 24 24" width="11" height="11" fill="#4f38dc" aria-hidden>
              <path d="M12 2a7 7 0 0 0-7 7c0 5 7 13 7 13s7-8 7-13a7 7 0 0 0-7-7zm0 9.5a2.5 2.5 0 1 1 0-5 2.5 2.5 0 0 1 0 5z" />
            </svg>
            {hotel.location}
          </div>
        </div>

        <div className={styles.headerRight}>
          {hotel.fromPrice && (
            <div className={styles.priceBox}>
              <span className={styles.muted}>From</span>
              <strong>{hotel.fromPrice}</strong>
              <span className={styles.muted}>per night</span>
            </div>
          )}

          {hotel.review && (
            <div className={styles.scoreBox}>
              <div className={styles.scoreBadge}>{hotel.review.score.toFixed(1)}</div>
              <div>
                <strong>{hotel.review.label}</strong>
                <div className={styles.muted}>{hotel.review.count} reviews</div>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* Tabs */}
      <nav className={styles.tabs} role="tablist">
        {TABS.map((tab) => (
          <button
            key={tab}
            type="button"
            role="tab"
            aria-selected={activeTab === tab}
            className={activeTab === tab ? styles.tabActive : styles.tab}
            onClick={() => setActiveTab(tab)}
          >
            {tab}
          </button>
        ))}
      </nav>

      {/* Content */}
      <section className={styles.content}>
        <div className={styles.copy} role="tabpanel">
          {activeTab === "Overview" && (
            <>
              <h2>{hotel.heading}</h2>
              <p>{hotel.description}</p>

              {hotel.features.length > 0 && (
                <ul className={styles.features}>
                  {hotel.features.map((f) => (
                    <li key={f.label}>
                      <span className={styles.featureIcon} aria-hidden>
                        {ICONS[f.icon]}
                      </span>
                      {f.label}
                    </li>
                  ))}
                </ul>
              )}
            </>
          )}

          {activeTab === "Rooms" && (
            <>
              <h2>Rooms</h2>

              <p className={styles.stayNote}>
                {hotel.stayLabel
                  ? hotel.priced
                    ? `Prices for ${hotel.stayLabel}`
                    : `No availability found for ${hotel.stayLabel}`
                  : "Choose your dates to see prices."}
              </p>

              {hotel.rooms.length === 0 ? (
                <p>No room information available for this hotel.</p>
              ) : (
                <div className={styles.roomList}>
                  {hotel.rooms.map((r) => {
                    const idx = roomPhoto[r.code] ?? 0;
                    const current = r.images[idx] ?? r.images[0];
                    const isOpen = !!expanded[r.code];
                    const shown = isOpen ? r.facilities : r.facilities.slice(0, VISIBLE_ROOM_FACILITIES);
                    const hidden = r.facilities.length - VISIBLE_ROOM_FACILITIES;

                    return (
                      <article key={r.code} className={styles.roomCard}>
                        {/* images */}
                        <div className={styles.roomMedia}>
                          <div className={styles.roomHero}>
                            {current && <img src={current.full} alt={`${r.title} photo ${idx + 1}`} loading="lazy" />}
                          </div>

                          {r.images.length > 1 && (
                            <div className={styles.roomThumbs}>
                              {r.images.map((g, i) => (
                                <button
                                  key={`${r.code}-${i}`}
                                  type="button"
                                  aria-label={`Show photo ${i + 1} of ${r.title}`}
                                  aria-pressed={i === idx}
                                  className={i === idx ? styles.roomThumbActive : styles.roomThumb}
                                  onClick={() => setRoomPhoto((p) => ({ ...p, [r.code]: i }))}
                                >
                                  <img src={g.thumb} alt="" loading="lazy" />
                                </button>
                              ))}
                            </div>
                          )}
                        </div>

                        {/* details */}
                        <div className={styles.roomBody}>
                          <h3 className={styles.roomTitle}>{r.title}</h3>

                          <p className={styles.roomMeta}>
                            {[r.type, r.characteristic].filter(Boolean).join(" · ")}
                          </p>

                          <p className={styles.roomMeta}>
                            👥{" "}
                            {r.minPax && r.maxPax && r.minPax !== r.maxPax
                              ? `${r.minPax}–${r.maxPax}`
                              : r.maxPax}{" "}
                            guests
                            {r.maxAdults ? ` · up to ${r.maxAdults} adults` : ""}
                            {r.maxChildren ? ` · ${r.maxChildren} children` : ""}
                          </p>

                          {r.beds.length > 0 && <p className={styles.roomMeta}>🛏 {r.beds.join(", ")}</p>}

                          {r.facilities.length > 0 && (
                            <>
                              <ul className={styles.roomFacilities}>
                                {shown.map((f) => (
                                  <li key={f.label}>
                                    <span className={styles.roomIcon} aria-hidden>
                                      {f.icon}
                                    </span>
                                    {f.label}
                                  </li>
                                ))}
                              </ul>
                              {hidden > 0 && (
                                <button
                                  type="button"
                                  className={styles.roomMore}
                                  onClick={() => setExpanded((e) => ({ ...e, [r.code]: !isOpen }))}
                                >
                                  {isOpen ? "Show less" : `+${hidden} more`}
                                </button>
                              )}
                            </>
                          )}
                        </div>

                        {/* prices */}
                        {r.rates.length > 0 ? (
                          <div className={styles.roomRates}>
                            {r.rates.map((rt) => (
                              <div key={rt.key} className={styles.roomRate}>
                                <div className={styles.rateInfo}>
                                  <strong>{rt.board}</strong>
                                  <div className={styles.rateMuted}>{rt.cancel}</div>
                                  {rt.payment && <div className={styles.rateMuted}>{rt.payment}</div>}
                                  {rt.taxNote && <div className={styles.rateMuted}>{rt.taxNote}</div>}
                                  {rt.allotment > 0 && rt.allotment <= 5 && (
                                    <div className={styles.rateWarn}>Only {rt.allotment} left</div>
                                  )}
                                </div>

                                <div className={styles.ratePrice}>
                                  <div className={styles.rateTotal}>{rt.total}</div>
                                  {rt.sub && <div className={styles.rateMuted}>{rt.sub}</div>}
                                </div>

                                <Link href={rt.href} prefetch={false} className={styles.selectBtn}>
                                  Book now
                                </Link>
                              </div>
                            ))}
                          </div>
                        ) : (
                          hotel.stayLabel && (
                            <div className={styles.roomRates}>
                              <div className={styles.roomRate}>
                                <span className={styles.rateMuted}>Not available for your dates</span>
                              </div>
                            </div>
                          )
                        )}
                      </article>
                    );
                  })}
                </div>
              )}
            </>
          )}

          {activeTab === "Facilities" && (
            <>
              <h2>Facilities</h2>
              <ul className={styles.features}>
                {hotel.checkIn && (
                  <li>
                    <span className={styles.featureIcon} aria-hidden>🔑</span>
                    Check-in from {hotel.checkIn}
                  </li>
                )}
                {hotel.checkOut && (
                  <li>
                    <span className={styles.featureIcon} aria-hidden>🧳</span>
                    Check-out until {hotel.checkOut}
                  </li>
                )}
                {hotel.facilities.map((f) => (
                  <li key={f.label}>
                    <span className={styles.featureIcon} aria-hidden>
                      {f.icon}
                    </span>
                    {f.label}
                  </li>
                ))}
              </ul>
            </>
          )}

          {activeTab === "Location" && (
            <>
              <h2>Location</h2>
              <p>{hotel.address}</p>
              <ul className={styles.features}>
                {hotel.distances.map((d) => (
                  <li key={d.label}>
                    {d.label}: {d.value}
                  </li>
                ))}
              </ul>
            </>
          )}

          {activeTab === "Reviews" && (
            <>
              <h2>Reviews</h2>
              <p>
                {hotel.review
                  ? `${hotel.review.count} guest reviews.`
                  : "Guest reviews are not available for this hotel yet."}
              </p>
            </>
          )}
        </div>

        <div className={styles.mapCard}>
          <div className={styles.map}>
            <span className={styles.mapPin} />
          </div>
          {hotel.mapUrl && (
            <a href={hotel.mapUrl} target="_blank" rel="noopener noreferrer" className={styles.viewMap}>
              View on Map
            </a>
          )}
        </div>
      </section>
    </div>
  );
}